import { fileURLToPath } from 'node:url';
import { migrate } from 'drizzle-orm/node-postgres/migrator';
import { createDb } from './client';

export const MIGRATIONS_FOLDER = fileURLToPath(new URL('./migrations', import.meta.url));

/** Apply every pending SQL migration in src/db/migrations (generated by drizzle-kit). */
export async function runMigrations(url: string, ssl = false): Promise<void> {
  const handle = createDb({ url, ssl, max: 1 });
  try {
    await migrate(handle.db, { migrationsFolder: MIGRATIONS_FOLDER });
  } finally {
    await handle.close();
  }
}

// `npm run db:migrate -w @tgs/backend`
if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const url = process.env.DATABASE_URL;
  if (!url) {
    console.error('DATABASE_URL is not set (backend/.env).');
    process.exit(1);
  }
  runMigrations(url, process.env.DATABASE_SSL === 'true')
    .then(() => console.log('Migrations applied.'))
    .catch((err) => {
      console.error(err);
      process.exit(1);
    });
}
